// Playwright MCP function. Inject fresh one-use links at runtime; never save their values.
async (page) => {
 const context=await page.context().browser().newContext({viewport:{width:1440,height:1000},locale:'zh-CN'}),p=await context.newPage(),checks=[],errors=[];
 p.on('pageerror',e=>errors.push(e.message));
 const check=(name,condition)=>{if(!condition)throw Error(name);checks.push(name);};
 const activate=async link=>{const tab=await context.newPage();await tab.goto(link);await tab.close();};
 try{
  await p.goto('http://127.0.0.1:4180/prototype/orders.html');await p.locator('#notice').waitFor({state:'visible'});check('unauthenticated page blocks create',await p.locator('#new-order').isDisabled());
  await activate('__ACTIVATION_LINK__');await p.locator('#reconnect').click();await p.waitForFunction(()=>!document.querySelector('#refresh-list').disabled);
  await p.route('**/api/ops/v1/orders?*',async route=>{await new Promise(resolve=>setTimeout(resolve,500));await route.fulfill({status:200,contentType:'application/json',body:JSON.stringify({items:[],nextCursor:null})});});
  await p.locator('#refresh-list').click();check('loading state is observable',(await p.locator('#order-rows').innerText()).includes('正在读取'));await p.waitForFunction(()=>!document.querySelector('#refresh-list').disabled);check('injected empty list has a create path',(await p.locator('#order-rows').innerText()).includes('还没有草稿')&&!await p.locator('#new-order').isDisabled());await p.unroute('**/api/ops/v1/orders?*');
  await p.locator('#new-order').click();
  await p.locator('#save-order').click();check('validation focuses first invalid field',await p.locator('[name="pickup.address"]').evaluate(n=>n===document.activeElement&&n.getAttribute('aria-invalid')==='true'));
  await p.locator('#fill-sample').click();await p.waitForFunction(()=>document.querySelector('[name="pickup.address"]').value==='DEMO warehouse entrance');
  await p.locator('#customer').click();await p.keyboard.press('ArrowDown');await p.keyboard.press('Enter');await p.keyboard.press('Escape');
  await p.locator('[data-step="cargo"]').click();await p.locator('#add-item').click();await p.locator('[name="items.1.name"]').fill('DEMO second box');await p.locator('[name="items.1.unknownReason"]').fill('Awaiting warehouse measurement');
  await p.locator('[data-step="service"]').click();await p.locator('[name="notes"]').fill('Browser evidence '+Date.now());
  const create=p.waitForResponse(r=>r.url().endsWith('/api/ops/v1/orders')&&r.request().method()==='POST');await p.locator('#save-order').click();const created=await create,detail=await created.json();check('create committed with two cargo lines',created.status()===201&&detail.items.length===2&&detail.order.version===1);
  await p.locator('#orders-list').waitFor({state:'visible'});await p.reload();await p.locator(`[data-open="${detail.order.id}"]`).click();
  await p.locator('[data-step="cargo"]').click();check('reload reads persistent cargo',await p.locator('[name="items.1.name"]').inputValue()==='DEMO second box');
  await p.locator('[data-step="service"]').click();check('Cambodia time round trip',await p.locator('[name="requestedPickupWindow.start"]').inputValue()==='2026-10-26T09:00');
  await p.locator('[name="notes"]').fill('my retained edit');await p.locator('#back-list').click();await p.locator('#leave-dialog').waitFor({state:'visible'});await p.keyboard.press('Escape');check('Escape keeps unsaved edits',await p.locator('[name="notes"]').inputValue()==='my retained edit');
  const external=await p.evaluate(async d=>{const s=await(await fetch('/dev/session')).json();d.draft.notes='external committed version';d.draft.requestedPickupWindow.start='2026-10-26T02:00:30Z';const r=await fetch('/api/ops/v1/orders/'+d.order.id,{method:'PATCH',headers:{'Content-Type':'application/json','X-CSRF-Token':s.csrfToken,'Idempotency-Key':crypto.randomUUID(),'If-Match':'"1"'},body:JSON.stringify(d.draft)});return r.status;},detail);check('second writer commits',external===200);
  await p.locator('#save-order').click();await p.locator('#conflict').waitFor({state:'visible'});check('412 retains local input',await p.locator('[name="notes"]').inputValue()==='my retained edit');
  await p.locator('#compare-latest').click();await p.locator('#use-latest').waitFor({state:'visible'});check('conflict exposes latest source', (await p.locator('#latest-summary').innerText()).includes('external committed version'));
  await p.locator('#use-latest').click();await p.locator('#leave').click();await p.locator('[data-step="service"]').click();check('explicit discard loads version 2',await p.locator('[name="notes"]').inputValue()==='external committed version');
  await p.locator('[name="notes"]').fill('final normal edit');const edit=p.waitForResponse(r=>r.request().method()==='PATCH');await p.locator('#save-order').click();const edited=await edit;const editedBody=await edited.json();check('edit commits version 3',edited.status()===200&&editedBody.order.version===3);check('unchanged time preserves source seconds',editedBody.draft.requestedPickupWindow.start==='2026-10-26T02:00:30Z');
  await p.locator('#new-order').click();await p.locator('#fill-sample').click();await p.waitForFunction(()=>document.querySelector('[name="pickup.address"]').value==='DEMO warehouse entrance');
  const requests=[];let lostId;
  await p.route('**/api/ops/v1/orders',async route=>{if(route.request().method()!=='POST')return route.continue();requests.push({key:route.request().headers()['idempotency-key'],body:route.request().postData()});if(requests.length===1){const r=await route.fetch();lostId=(await r.json()).order.id;await route.abort('failed');}else await route.continue();});
  await p.locator('#save-order').click();await p.locator('#retry-save').waitFor({state:'visible'});await p.waitForFunction(()=>document.querySelector('#editor-fields').disabled);check('lost response freezes inputs',await p.locator('[name="pickup.address"]').isDisabled());
  const retry=p.waitForResponse(r=>r.request().method()==='POST');await p.locator('#retry-save').click();const replay=await retry;check('retry reuses committed order',replay.headers()['idempotent-replayed']==='true'&&(await replay.json()).order.id===lostId);check('retry has identical key and payload',requests.length===2&&JSON.stringify(requests[0])===JSON.stringify(requests[1]));await p.unroute('**/api/ops/v1/orders');
  await p.locator('#new-order').click();await p.locator('#fill-sample').click();await p.waitForFunction(()=>document.querySelector('[name="pickup.address"]').value==='DEMO warehouse entrance');
  await p.evaluate(async()=>{const s=await(await fetch('/dev/session')).json();await fetch('/dev/session/logout',{method:'POST',headers:{'X-CSRF-Token':s.csrfToken}});});
  await p.locator('#save-order').click();await p.waitForFunction(()=>document.querySelector('#connection').textContent.includes('会话不可用'));check('expired session keeps form',await p.locator('[name="pickup.address"]').inputValue()==='DEMO warehouse entrance');
  await activate('__REAUTH_LINK__');await p.locator('#reconnect').click();await p.locator('#retry-save').click();await p.locator('#orders-list').waitFor({state:'visible'});check('same identity reauthentication completes original write',true);
  await context.setOffline(true);await p.locator('#refresh-list').click();await p.waitForFunction(()=>document.querySelector('#order-rows').textContent.includes('读取失败'));check('offline list is not an empty success',true);await context.setOffline(false);await p.locator('#refresh-list').click();await p.waitForFunction(()=>document.querySelector('#order-rows [data-open]'));
  if(!await p.locator('#next-page').isDisabled()){await p.locator('#next-page').click();await p.waitForFunction(()=>document.querySelector('#page-range').textContent.startsWith('第 2 页'));check('real cursor advances page',await p.locator('[data-open]').count()>0);await p.locator('#previous-page').click();await p.waitForFunction(()=>document.querySelector('#page-range').textContent.startsWith('第 1 页'));check('previous cursor restores page',true);}
  if(await p.locator('#toast.show button').count())await p.locator('#toast.show button').click();await p.screenshot({path:'E:/Dr.RouteFit/services/routefit/verification/order-entry-ui/desktop.png',fullPage:true});
  await p.locator('#new-order').click();await p.locator('#fill-sample').click();await p.waitForFunction(()=>document.querySelector('[name="pickup.address"]').value==='DEMO warehouse entrance');await p.locator('[data-step="cargo"]').click();
  await p.setViewportSize({width:390,height:844});await p.emulateMedia({reducedMotion:'reduce'});check('mobile body has no horizontal overflow',await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await p.screenshot({path:'E:/Dr.RouteFit/services/routefit/verification/order-entry-ui/mobile.png',fullPage:true});
  await activate('__OTHER_IDENTITY_LINK__');await p.locator('#reconnect').click();await p.locator('#orders-list').waitFor({state:'visible'});check('identity switch clears previous form',await p.locator('#contacts-fields input').count()===0);await p.waitForFunction(()=>!document.querySelector('#refresh-list').disabled);check('other company cannot see previous order',await p.locator(`[data-open="${detail.order.id}"]`).count()===0);
  check('no browser JavaScript errors',errors.length===0);return {checks,errors,ordersCreated:3,orderId:detail.order.id};
 }finally{await context.close();}
}
